function validate_canonical_schedule(string $path): array
{
    if (!is_file($path)) {
        throw new RuntimeException('Canonical schedule missing: ' . $path);
    }

    $raw = file_get_contents($path);
    if ($raw === false || trim($raw) === '') {
        throw new RuntimeException('Canonical schedule is unreadable or empty: ' . $path);
    }

    $data = json_decode($raw, true);
    if (!is_array($data)) {
        throw new RuntimeException('Canonical schedule is invalid JSON: ' . $path);
    }

    if ((int)($data['year'] ?? 0) !== 2026) {
        throw new RuntimeException('Canonical schedule year is not 2026.');
    }

    $races = $data['mrl_points_races'] ?? null;
    if (!is_array($races) || count($races) < 30) {
        throw new RuntimeException('Canonical schedule does not contain a usable mrl_points_races list.');
    }

    $hasR27 = false;
    foreach ($races as $race) {
        if (!is_array($race)) {
            continue;
        }
        $rn = (int)($race['mrl_race_number'] ?? $race['race_number'] ?? 0);
        if ($rn === 27 && trim((string)($race['start_at'] ?? '')) !== '') {
            $hasR27 = true;
            break;
        }
    }

    if (!$hasR27) {
        throw new RuntimeException('Canonical schedule does not contain a timed R27 entry.');
    }

    return [
        'generated_at' => (string)($data['generated_at'] ?? ''),
        'source' => (string)($data['source'] ?? ''),
        'points_races' => count($races),
    ];
}

$host = strtolower((string)($_SERVER['HTTP_HOST'] ?? ''));
$host = preg_replace('/:\d+$/', '', $host);

$root = __DIR__;
$targets = [
    'race_results/race_schedule_helper.php' => [
        'path' => $root . '/race_results/race_schedule_helper.php',
        'expected' => 'VERSION: v002',
        'after' => 'VERSION: v003',
    ],
    'team.php' => [
        'path' => $root . '/team.php',
        'expected' => 'VERSION: v017',
        'after' => 'VERSION: v018',
    ],
    'race_results/race_results_rd_helper.php' => [
        'path' => $root . '/race_results/race_results_rd_helper.php',
        'expected' => 'VERSION: v003',
        'after' => 'VERSION: v004',
    ],
];

$canonicalSchedule = $root . '/race_results/_race_results_schedule.json';
$backupDir = $root . '/mrl_unified_schedule_backup_' . INSTALLER_TIMESTAMP;

$errors = [];
$prepared = [];
$scheduleInfo = [];

if ($host !== REQUIRED_HOST) {
    $errors[] = 'REFUSED: installer may run only on ' . REQUIRED_HOST . '. Current host: ' . ($host !== '' ? $host : '(unknown)');
}

try {
    $scheduleInfo = validate_canonical_schedule($canonicalSchedule);
} catch (Throwable $e) {
    $errors[] = $e->getMessage();
}

foreach ($targets as $label => $meta) {
    $path = $meta['path'];

    if (!is_file($path)) {
        $errors[] = $label . ': file not found.';
        continue;
    }

    if (!is_readable($path)) {
        $errors[] = $label . ': file is not readable.';
        continue;
    }

    if (!is_writable($path)) {
        $errors[] = $label . ': file is not writable.';
        continue;
    }

    $src = file_get_contents($path);
    if ($src === false) {
        $errors[] = $label . ': unable to read file.';
        continue;
    }

    if (strpos($src, $meta['expected']) === false) {
        $errors[] = $label . ': expected source version not found (' . $meta['expected'] . ').';
        continue;
    }

    try {
        if ($label === 'race_results/race_schedule_helper.php') {
            $new = new_race_schedule_helper();
        } elseif ($label === 'team.php') {
            $new = patch_team_php($src);
        } else {
            $new = patch_rd_helper($src);
        }

        if (strpos($new, $meta['after']) === false) {
            throw new RuntimeException($label . ': transformed version marker not found.');
        }

        $prepared[$label] = [
            'path' => $path,
            'old' => $src,
            'new' => $new,
        ];
    } catch (Throwable $e) {
        $errors[] = $e->getMessage();
    }
}

$installRequested = ($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST'
    && isset($_POST['install_unified_schedule']);

$installed = false;
$installMessage = '';

if ($installRequested && empty($errors)) {
    try {
        if (!is_dir($backupDir) && !mkdir($backupDir, 0755, true)) {
            throw new RuntimeException('Unable to create backup folder: ' . $backupDir);
        }

        foreach ($prepared as $label => $row) {
            $backupPath = $backupDir . '/' . str_replace('/', '__', $label);
            if (file_put_contents($backupPath, $row['old'], LOCK_EX) === false) {
                throw new RuntimeException('Unable to create backup: ' . $backupPath);
            }
        }

        foreach ($prepared as $label => $row) {
            atomic_write($row['path'], $row['new']);
        }

        $installed = true;
        $installMessage = 'INSTALL COMPLETE: LP/RD now use /race_results/_race_results_schedule.json as the shared race schedule source. Backups saved in ' . basename($backupDir) . '.';
    } catch (Throwable $e) {
        $errors[] = 'INSTALL FAILED: ' . $e->getMessage();
    }
}

